<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/core.php';
require dirname(__DIR__).'/app/features.php';
$dir=sys_get_temp_dir().'/xfedi-test-'.bin2hex(random_bytes(8)); mkdir($dir,0700);
putenv('XFEDI_DATA_DIR='.$dir); putenv('XFEDI_URL=https://social.example/xsukax_fediverse.php');
$checks=0;
function check(bool $value,string $message): void { global $checks; if (!$value) throw new RuntimeException('FAIL '.$message); $checks++; }
try {
    db()->exec(file_get_contents(__DIR__.'/legacy.sql'));
    $key=openssl_pkey_new(['private_key_bits'=>2048]); openssl_pkey_export($key,$private); $public=openssl_pkey_get_details($key)['key'];
    executeSql('INSERT INTO users(id,username,name,bio,password_hash,private_key,public_key,created_at) VALUES(1,?,?,?,?,?,?,?)',['alice','Alice','Old profile',password_hash('test-password-1234',PASSWORD_DEFAULT),$private,$public,1700000000]);
    executeSql('INSERT INTO posts(id,content,created_at,updated_at,deleted) VALUES(1,?,1700000000,1700000000,0)',['Original #Test']);
    executeSql('INSERT INTO posts(id,content,created_at,updated_at,deleted) VALUES(2,?,1700000001,1700000001,1)',['Deleted original']);
    initDb(); initDb();
    check(user()['private_key']===$private && user()['public_key']===$public,'migration preserves signing keys');
    check(user()['bio']==='Old profile' && user()['username']==='alice','migration preserves profile');
    check((int)queryOne('SELECT deleted FROM posts WHERE id=2')['deleted']===1,'migration preserves deletion state');
    check(noteUrl(1)==='https://social.example/xsukax_fediverse.php?ap=note&id=1','stable legacy note identity');
    check(actorUrl()==='https://social.example/xsukax_fediverse.php?ap=actor','stable legacy actor identity');
    check(user()['timezone']==='UTC','timezone migration default');
    check((int)queryOne('SELECT COUNT(*) n FROM tags')['n']===1,'old posts receive hashtag index');
    putenv('XFEDI_URL=https://other.example/index.php'); $refused=false;
    try { initDb(); } catch (Throwable) { $refused=true; }
    check($refused,'configured identity cannot silently change'); putenv('XFEDI_URL=https://social.example/xsukax_fediverse.php');
    check(localUrl('page=profile')==='https://social.example/@alice','readable profile URL');
    check(localUrl('page=post&id=1')==='https://social.example/@alice/1','readable post URL');
    check(localUrl('page=tag&tag=café')==='https://social.example/tags/caf%C3%A9','unicode hashtag URL');
    check(localNoteId(noteUrl(1))===1 && localNoteId('https://evil.example/xsukax_fediverse.php?ap=note&id=1')===0,'local note ID origin binding');
    foreach (['http://example.com','https://127.0.0.1','https://localhost','https://user:pass@example.com','https://example.com:22','https://example.com/\\evil','https://example.com/\n'] as $url) check(!isSafePublicUrl($url),'unsafe URL rejected');
    foreach (['127.0.0.1','10.0.0.5','192.168.1.1','169.254.169.254','::1','fd00::1','::ffff:8.8.8.8','100.100.100.200','224.0.0.1','198.18.0.1','192.0.0.1','192.0.2.1','203.0.113.1','2001:db8::1','2002:7f00:1::1','3fff::1'] as $ip) check(!publicIp($ip),'unsafe IP rejected');
    check(isSafePublicUrl('https://remote.example/users/bob'),'valid public hostname');
    check(publicIp('8.8.8.8') && publicIp('2606:4700:4700::1111'),'valid public IP');
    $x=sanitizeRemoteHtml('<p onclick="bad()">Hi <script>alert(1)</script><a href="javascript:bad()">bad</a><a href="https://example.com">safe</a><img src=x onerror=bad()></p>');
    check(!str_contains($x,'script') && !str_contains($x,'onclick') && !str_contains($x,'javascript') && !str_contains($x,'onerror') && str_contains($x,'https://example.com'),'remote HTML sanitized');
    check(websiteProof('<a href="https://social.example/@alice" rel="nofollow ME">me</a>','https://site.example',['https://social.example/@alice']),'rel me verification');
    check(websiteProof('<link rel="me" href="/profile">','https://site.example/a',['https://site.example/profile']),'relative rel me resolution');
    check(!websiteProof('<a href="https://evil.example/@alice" rel="me">me</a>','https://site.example',['https://social.example/@alice']),'mismatched profile not verified');
    check(!websiteProof('<iframe srcdoc="&lt;a rel=me href=https://social.example/@alice&gt;"></iframe>','https://site.example',['https://social.example/@alice']),'embedded proof not accepted');
    $actor='https://remote.example/users/bob';
    executeSql('INSERT INTO remote_actors(id,handle,username,name,inbox,key_id,public_key,fetched_at) VALUES(?,?,?,?,?,?,?,?)',[$actor,'@bob@remote.example','bob','Bob','https://remote.example/inbox',$actor.'/main-key',$public,time()]);
    $sender=queryOne('SELECT * FROM remote_actors WHERE id=?',[$actor]);
    $follow=['id'=>'https://remote.example/a/follow','type'=>'Follow','actor'=>$actor,'object'=>actorUrl()];
    enqueueInbox($follow,$sender); enqueueInbox($follow,$sender);
    check((int)queryOne('SELECT COUNT(*) n FROM inbox_jobs')['n']===1,'durable inbox deduplication');
    processInbox();
    check((int)queryOne('SELECT COUNT(*) n FROM followers')['n']===1,'incoming Follow');
    check((int)queryOne('SELECT COUNT(*) n FROM deliveries')['n']===1,'Accept delivery queued');
    handleInbox($follow,$sender);
    $follow['id']='https://remote.example/a/another-follow';handleInbox($follow,$sender);
    check((int)queryOne("SELECT COUNT(*) n FROM notifications WHERE kind='follow'")['n']===1,'follow notifications deduplicated');
    handleInbox(['id'=>'https://remote.example/a/unfollow','type'=>'Undo','actor'=>$actor,'object'=>$follow],$sender);
    $follow['id']='https://remote.example/a/follow-again';handleInbox($follow,$sender);
    check((int)queryOne("SELECT COUNT(*) n FROM notifications WHERE kind='follow'")['n']===2,'a new follow after unfollow creates a new notification');
    $request=newActivity('Follow',$actor,[$actor]);
    executeSql('INSERT INTO follows(actor_id,follow_id,status,created_at) VALUES(?,?,?,?)',[$actor,$request['id'],'pending',time()]);
    handleInbox(['id'=>'https://remote.example/a/accept','type'=>'Accept','actor'=>$actor,'object'=>$request],$sender);
    check(queryOne('SELECT status FROM follows')['status']==='accepted','Accept correlates original Follow');
    $note=['id'=>'https://remote.example/notes/1','type'=>'Note','attributedTo'=>$actor,'content'=>'<p>Hello @alice@social.example #Test</p>','to'=>[AS_PUBLIC,actorUrl()],'inReplyTo'=>noteUrl(1),'published'=>nowIso(time()-10),'updated'=>nowIso(time()-10)];
    handleInbox(['id'=>'https://remote.example/a/create','type'=>'Create','actor'=>$actor,'object'=>$note],$sender);
    check(knownPost($note['id'])!==null,'public incoming note saved');
    check((int)queryOne("SELECT COUNT(*) n FROM notifications WHERE kind='reply' AND object_id=?",[$note['id']])['n']===1,'reply links to originating post');
    check((int)queryOne("SELECT COUNT(*) n FROM notifications WHERE kind='mention'")['n']===1,'mention notification');
    $note['content']='<p>Edited</p>'; $note['updated']=nowIso(); noteInbound($note,$actor,false);
    check(knownPost($note['id'])['content']==='Edited','incoming newer Update');
    $note['content']='Out of order';$note['updated']=nowIso(time()-30);noteInbound($note,$actor,true);
    check(knownPost($note['id'])['content']==='Edited','stale Update ignored');
    $privateNote=$note;$privateNote['id']='https://remote.example/notes/private';$privateNote['to']=[actorUrl()];$privateNote['cc']=[];noteInbound($privateNote,$actor,true,true);
    check(knownPost($privateNote['id'])===null,'non-public notes never leak');
    $like=['id'=>'https://remote.example/a/like','type'=>'Like','actor'=>$actor,'object'=>noteUrl(1)];handleInbox($like,$sender);handleInbox($like,$sender);
    check((int)queryOne('SELECT COUNT(*) n FROM likes_remote')['n']===1,'incoming Like idempotent');
    handleInbox(['id'=>'https://remote.example/a/unlike','type'=>'Undo','actor'=>$actor,'object'=>$like],$sender);
    check((int)queryOne('SELECT COUNT(*) n FROM likes_remote')['n']===0,'Undo Like');
    $like['id']='https://remote.example/a/like-again';handleInbox($like,$sender);
    check((int)queryOne("SELECT COUNT(*) n FROM notifications WHERE kind='like'")['n']===2,'favourite after undo notifies again');
    $boost=['id'=>'https://remote.example/a/boost','type'=>'Announce','actor'=>$actor,'object'=>noteUrl(1),'to'=>[AS_PUBLIC]];handleInbox($boost,$sender);
    check((int)queryOne('SELECT COUNT(*) n FROM boosts_remote')['n']===1,'incoming Announce');
    $duplicate=$boost;$duplicate['id']='https://remote.example/a/duplicate-boost';handleInbox($duplicate,$sender);
    check((int)queryOne("SELECT COUNT(*) n FROM notifications WHERE kind='boost'")['n']===1,'a second activity for an existing boost does not notify twice');
    handleInbox(['id'=>'https://remote.example/a/unboost','type'=>'Undo','actor'=>$actor,'object'=>$boost['id']],$sender);
    check((int)queryOne('SELECT COUNT(*) n FROM boosts_remote')['n']===0,'Undo Announce by reference');
    $boost['id']='https://remote.example/a/boost-again';handleInbox($boost,$sender);
    check((int)queryOne("SELECT COUNT(*) n FROM notifications WHERE kind='boost'")['n']===2,'a new boost after undo notifies again');
    handleInbox(['id'=>'https://remote.example/a/delete','type'=>'Delete','actor'=>$actor,'object'=>$note['id']],$sender);
    $note['updated']=nowIso(time()+10);noteInbound($note,$actor,true);
    check(knownPost($note['id'])===null,'Delete cannot be resurrected');
    $body=jenc(['id'=>'https://remote.example/a/signed','type'=>'Like','actor'=>$actor,'object'=>noteUrl(1)]);
    $_SERVER['HTTP_HOST']='social.example';$_SERVER['REQUEST_URI']='/xsukax_fediverse.php?ap=inbox';$_SERVER['HTTP_DATE']=gmdate('D, d M Y H:i:s').' GMT';$_SERVER['HTTP_DIGEST']='SHA-256='.base64_encode(hash('sha256',$body,true));
    $base='(request-target): post '.$_SERVER['REQUEST_URI']."\nhost: social.example\ndate: ".$_SERVER['HTTP_DATE']."\ndigest: ".$_SERVER['HTTP_DIGEST'];
    openssl_sign($base,$raw,$private,OPENSSL_ALGO_SHA256);
    $_SERVER['HTTP_SIGNATURE']='keyId="'.$sender['key_id'].'",algorithm="rsa-sha256",headers="(request-target) host date digest",signature="'.base64_encode($raw).'"';
    check(verifyInbox($body)['id']===$actor,'signature verification preserves original legacy target and separate key ID');
    $_SESSION=['uid'=>1];executeSql('UPDATE users SET timezone=?',['Africa/Addis_Ababa']);
    check(displayTime(0,'H:i')==='03:00','selected timezone display');
    $_SESSION=[];check(displayTime(0,'H:i')==='00:00','anonymous timestamps UTC');
    $obj=noteObject(queryOne('SELECT * FROM posts WHERE id=1'));
    check($obj['id']===noteUrl(1) && $obj['url']==='https://social.example/@alice/1','object ID stable with readable permalink');
    check(str_contains(actorObject()['publicKey']['publicKeyPem'],'BEGIN PUBLIC KEY'),'actor includes public key only');
    echo "PASS $checks core and migration checks\n";
} finally {
    foreach (glob($dir.'/*')?:[] as $file) unlink($file); rmdir($dir);
}
